\"\"\"Canonicalize a person's display name to the company house style.\"\"\"

PARTICLES = {"van","von","de","la","del","della","di","du","da","der","den","ten","ter","bin","al"}
SUFFIX_ROMAN = {"ii","iii","iv","v","vi","vii","viii"}

def canon(name):
    words = name.split()
    out = []
    i = 0
    n = len(words)
    while i < n:
        w = words[i]
        wl = w.lower().rstrip(".")
        if len(wl) == 1 and wl.isalpha():
            grp = []
            while i < n:
                t = words[i].lower().rstrip(".")
                if len(t) == 1 and t.isalpha():
                    grp.append(t.upper())
                    i += 1
                else:
                    break
            out.append(".".join(grp) + ".")
            continue
        elif wl in PARTICLES and len(out) > 0:
            out.append(wl)
        elif wl in SUFFIX_ROMAN:
            out.append(wl.upper())
        elif wl in ("jr","sr"):
            out.append(wl.capitalize() + ".")
        elif wl.startswith("mc") and len(wl) > 2:
            out.append("Mc" + w[2:].capitalize())
        elif wl.startswith("mac") and len(wl) > 3:
            out.append("Mac" + w[3:].capitalize())
        else:
            out.append(w.capitalize())
        i += 1
    return " ".join(out)

